$\begin{align}
&\phantom{=}\dfrac{dy}{dx}
\\\\
&=\dfrac{d}{dx}\left(\sqrt{x}e^x\right)
\\\\
&=\dfrac{d}{dx}\left(\sqrt{x}\right)e^x+\sqrt{x}\dfrac{d}{dx}(e^x)&&\gray{\text{The product rule}}
\\\\
&=\dfrac{d}{dx}\left(x^{^{\Large\frac{1}{2}}}\right)e^x+\sqrt{x}\dfrac{d}{dx}(e^x)&&\gray{\text{Write } \sqrt{x}\text{ as a power}}
\\\\
&=\dfrac12x^{^{\Large-\frac{1}{2}}}\cdot e^x+\sqrt{x}\cdot e^x&&\gray{\text{Differentiate }x^{^{\Large\frac{1}{2}}}\text{ and }e^x}
\\\\
&=e^x\left(\dfrac{1}{2\sqrt{x}}+\sqrt{x}\right)&&\gray{\text{Simplify}}
\end{align}$
